import Link from 'next/link';
import React from 'react'
import { Button } from './ui/button';
import Image from 'next/image';

const HeroSection = () => {
  return <div className='pb-20 px-4'>
    <div className='container mx-auto text-center'>
        <h1 className='text-4xl md:text-8xl lg:text-[105px] pb-6 gradient-title'> 
            Manage Your Finance <br/> With Intelligence 
        </h1>
        <p> AI powered financial intelligence that will streamline all your finance related tasks</p>
        <div>
            <Link href="/dashboard">
            <Button size ='lg' className='px-8'>
                Get Started 
            </Button>
            </Link>
            <Link href="https://www.google.com" target='_blank'>
            <Button size ='lg'variant='outline' className='px-8'>
                Watch Demo
            </Button>
            </Link>
        </div>
        <div>
            <Image 
            src='/banner.jpeg' 
            alt="banner"  
            className='rounded-lg shadow-2xl border mx-auto'
            width={1280} 
            height={720}
            />
        </div>
    </div>
  </div>;
  
}

export default HeroSection;